function doubleEach(nums) {
  // BUG: [...acc, x] copies the whole growing array each iteration -> O(n^2).
  let acc = [];
  for (const n of nums) {
    acc = [...acc, n * 2];
  }
  return acc;
}

module.exports = { doubleEach };

test_setup_files.test_perf.js:
const assert = require('node:assert');
const { doubleEach } = require('./scale.js');

assert.deepStrictEqual(doubleEach([1, 2, 3]), [2, 4, 6], 'basic correctness failed');
assert.deepStrictEqual(doubleEach([]), [], 'empty array failed');

const N = 60000;
const big = [];
for (let i = 0; i < N; i++) big.push(i);
const expected = big.map((x) => x * 2);

const t0 = Date.now();
const result = doubleEach(big);
const elapsedMs = Date.now() - t0;

assert.deepStrictEqual(result, expected, 'large-input result incorrect');
assert(
  elapsedMs < 1500,
  `doubleEach took ${elapsedMs}ms for ${N} elements; expected an O(n) push/map, not spreading the accumulator each iteration`
);

console.log('ok');

reference_solution.scale.js:
function doubleEach(nums) {
  const acc = [];
  for (const n of nums) {
    acc.push(n * 2);
  }
  return acc;
}

module.exports = { doubleEach };

